// Достаём поля запроса из webhook-нода. Поддерживаем оба варианта: top-level и body.
const hook = $('[chat] Webhook: POST /chat/ask').first().json || {};
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const message = (body.message || '').toString().trim();
const document_id = body.document_id ? String(body.document_id) : null;
// Набор документов активного проекта (фильтр интерфейса по проекту). Используется в режиме «по
// всей базе»: контекст ограничивается этими document_id. document_id (один) имеет приоритет.
const document_ids = Array.isArray(body.document_ids) ? body.document_ids.map(String).filter(Boolean) : [];
const history = Array.isArray(body.history) ? body.history.slice(-6) : [];
if (!message) {
  return [{ json: { _http_code: 400, _body: { detail: 'message is required' } } }];
}
return [{ json: { _http_code: 200, message, document_id, document_ids, history } }];

// Sub-workflow вернул 1 item { _idx, hits }. Превращаем hits в sources + формируем system/user prompt'ы для AI Agent.
const src = $('[chat] Parse Request').first().json || {};
const out = ($input.first() && $input.first().json) || {};
const hits = Array.isArray(out.hits) ? out.hits : [];

const sources = hits.map((h) => {
  const pl = h.payload || {};
  return {
    chunk_id: String(pl.paragraph_id || ''),
    content: pl.content || '',
    similarity_score: typeof h.score === 'number' ? h.score : 0,
    document_id: pl.document_id || '',
    source_document: pl.chapter_title || pl.document_title || pl.document_id || 'unknown',
  };
});

const contextText = sources.length
  ? sources
      .map(
        (s, i) => `[${i + 1}] (score=${s.similarity_score.toFixed(2)}) ${(s.content || '').trim()}`,
      )
      .join('\n')
  : '(контекст пуст)';

const history = Array.isArray(src.history) ? src.history : [];
const historyText = history.length
  ? 'История диалога:\n' +
    history
      .map((m) => `${m.role === 'user' ? 'Пользователь' : 'Ассистент'}: ${m.content || ''}`)
      .join('\n')
  : '';

const userPrompt =
  (historyText ? historyText + '\n\n' : '') +
  `Контекст из документов:\n${contextText}\n\nВопрос: ${src.message}\nОтвет:`;

const systemPrompt =
  'Ты — ассистент, отвечающий на вопросы по корпоративным документам. Используй ТОЛЬКО факты из приведённого контекста. Если ответа в контексте нет — честно скажи об этом. Отвечай кратко и по-русски.';

return [
  {
    json: {
      _system_prompt: systemPrompt,
      _user_prompt: userPrompt,
      sources,
      message: src.message,
      document_id: src.document_id,
    },
  },
];

// Мультипровайдерный вызов LLM для чата (свободный текст, БЕЗ принуждения к JSON).
// Провайдер берётся из config(key=llm_extraction) нодой [chat] Get LLM Config (dataTable) — ОБЩИЙ
// тумблер с обработкой документов (Merge Chunks). Заменяет нативные lmChatOllama + AI Agent (статичный
// credential не переключить). AI Agent был без tools/памяти: история диалога и RAG-контекст уже
// вшиты в _user_prompt нодой Build Prompt & Sources, поэтому замена эквивалентна.
const http = this.helpers.httpRequest.bind(this.helpers);
const src = $('[chat] Build Prompt & Sources').first().json || {};
const systemPrompt = src._system_prompt || '';
const userPrompt = src._user_prompt || '';

const OLLAMA = 'http://host.docker.internal:11434/api/chat';
let MODEL = 'qwen3:8b';
let DEVELONICA_URL =
  String('https://ai.develonica.group').replace(/\/+$/, '') +
  '/api/v1/chat/completions';
let LMSTUDIO_URL =
  String('http://192.168.2.135:1234/v1').replace(/\/+$/, '') +
  '/chat/completions';
let API_KEY = ''; let PROVIDER = 'ollama',
  CLAUDE_MODEL = 'claude-haiku-4-5',
  DEVELONICA_MODEL = String('dvl-analyst'),
  LMSTUDIO_MODEL = String('google/gemma-4-12b');
// Конфиг читаем нодой [chat] Get LLM Config (dataTable, без self-HTTP к localhost:5678 —
// на «чужих» стендах task-runner в отдельном контейнере, localhost не доходит до n8n).
{
  const _c = $('[chat] Get LLM Config').first();
  const lc = (_c && _c.json) || {};
  const _p = String(lc.provider || '').toLowerCase(); API_KEY = lc.api_key ? String(lc.api_key) : '';
  if (_p === 'claude') { PROVIDER = 'claude'; if (lc.model) CLAUDE_MODEL = String(lc.model); }
  else if (_p === 'develonica') { PROVIDER = 'develonica'; if (lc.model) DEVELONICA_MODEL = String(lc.model); if (lc.base_url) DEVELONICA_URL = String(lc.base_url).replace(/\/+$/, '') + '/api/v1/chat/completions'; }
  else if (_p === 'lmstudio') { PROVIDER = 'lmstudio'; if (lc.model) LMSTUDIO_MODEL = String(lc.model); if (lc.base_url) LMSTUDIO_URL = String(lc.base_url).replace(/\/+$/, '') + '/chat/completions'; }
}

const _sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const _httpStatus = (e) => {
  const s = e && (e.httpCode || e.statusCode || (e.response && (e.response.status || e.response.statusCode)) || (e.cause && e.cause.statusCode));
  if (s) return Number(s);
  const m = String((e && e.message) || '').match(/\b(429|529|500|502|503|504)\b/);
  return m ? Number(m[1]) : 0;
};
const _withRetry = async (fn) => {
  const MAX = 3;
  let delay = 1500;
  for (let attempt = 0; ; attempt++) {
    try { return await fn(); }
    catch (e) {
      const st = _httpStatus(e);
      const retriable = st === 429 || st === 529 || (st >= 500 && st <= 504) ||
        (st === 0 && /timeout|socket|network|ECONN|EAI_AGAIN|ETIMEDOUT|aborted/i.test(String((e && e.message) || '')));
      if (attempt >= MAX || !retriable) throw e;
      await _sleep(Math.min(delay, 20000));
      delay *= 2;
    }
  }
};

const callChat = async () => {
  if (PROVIDER === 'claude') {
    const r = await _withRetry(() => http({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages', json: true, timeout: 120000,
      headers: { 'x-api-key': (API_KEY || '').trim(), 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: CLAUDE_MODEL, max_tokens: 1500, temperature: 0.1, system: systemPrompt, messages: [{ role: 'user', content: userPrompt }] },
    }));
    return (r && r.content && r.content[0] && r.content[0].text) || '';
  }
  if (PROVIDER === 'develonica') {
    const r = await _withRetry(() => http({
      method: 'POST', url: DEVELONICA_URL, json: true, timeout: 120000,
      headers: { Authorization: 'Bearer ' + (API_KEY || '').trim(), 'content-type': 'application/json' },
      body: { model: DEVELONICA_MODEL, max_tokens: 1500, temperature: 0.1, stream: false, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }] },
    }));
    return (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
  }
  if (PROVIDER === 'lmstudio') {
    const r = await _withRetry(() => http({
      method: 'POST', url: LMSTUDIO_URL, json: true, timeout: 180000,
      headers: { Authorization: 'Bearer ' + (API_KEY || 'lm-studio').trim(), 'content-type': 'application/json' },
      body: { model: LMSTUDIO_MODEL, max_tokens: 1500, temperature: 0.1, stream: false, reasoning_effort: 'low', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }] },
    }));
    return (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
  }
  const r = await _withRetry(() => http({
    method: 'POST', url: OLLAMA, json: true, timeout: 180000,
    body: { model: MODEL, stream: false, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], options: { temperature: 0.1, num_ctx: 16384 } },
  }));
  return (r && r.message && r.message.content) || (r && r.response) || '';
};

let answer = '';
try { answer = await callChat(); } catch (e) { answer = ''; }
// Снимаем reasoning-блоки <think>…</think> (qwen3/gpt-oss отдают их в свободном тексте).
answer = String(answer || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
return [{ json: { output: answer, _provider: PROVIDER } }];

// AI Agent (toolsAgent) возвращает { output: '...' }; chainLlm возвращал { text }.
// Читаем оба поля для совместимости при будущих переключениях.
const llm = $input.first().json || {};
const answer = (llm.output || llm.text || llm.response || '').toString().trim();
const src = $('[chat] Build Prompt & Sources').first().json;
return [
  {
    json: {
      _http_code: 200,
      _body: { answer: answer || '(пустой ответ)', sources: src.sources || [] },
    },
  },
];

// Парсим query-параметры webhook GET. Контракт совместим с FastAPI /api/rag/search:
//   query (required), threshold (default 0.5), exclude_document_id (optional),
//   document_ids (optional, CSV — ограничение поиска документами активного проекта).
const hook = $('[ragSearch] Webhook: GET /rag/search').first().json || {};
const q =
  hook.query && typeof hook.query === 'object'
    ? hook.query
    : hook.params && typeof hook.params === 'object'
      ? hook.params
      : hook;
const query = (q.query || '').toString().trim();
const rawThr = q.threshold;
let threshold = 0.5;
if (rawThr !== undefined && rawThr !== null && rawThr !== '') {
  const parsed = Number(rawThr);
  if (!Number.isNaN(parsed)) threshold = parsed;
}
const exclude = q.exclude_document_id ? String(q.exclude_document_id) : null;
// document_ids приходит CSV-строкой (массивы в query-параметрах сериализуются неоднозначно).
const rawIds = q.document_ids;
const document_ids =
  typeof rawIds === 'string' && rawIds
    ? rawIds.split(',').map((s) => s.trim()).filter(Boolean)
    : Array.isArray(rawIds)
      ? rawIds.map(String).filter(Boolean)
      : [];
if (!query) {
  return [{ json: { _http_code: 400, _body: { detail: 'query is required' } } }];
}
return [{ json: { _http_code: 200, query, threshold, exclude_document_id: exclude, document_ids } }];

// Sub-workflow вернул 1 item { _idx, hits }. Превращаем в RagSearchResult[].
const out = ($input.first() && $input.first().json) || {};
const hits = Array.isArray(out.hits) ? out.hits : [];

const rows = hits.map((h) => {
  const pl = h.payload || {};
  const document_id = pl.document_id || '';
  return {
    chunk_id: String(pl.paragraph_id || ''),
    content: pl.content || '',
    similarity_score: typeof h.score === 'number' ? h.score : 0,
    source_document: pl.chapter_title || pl.document_title || document_id || 'unknown',
    metadata: Object.assign({}, pl, { document_id }),
  };
});

return [{ json: { _http_code: 200, _body: rows } }];

// Готовим 1 input item для wf_rag_search из распарсенного chat-запроса.
const src = $('[chat] Parse Request').first().json || {};
const includeIds = Array.isArray(src.document_ids) ? src.document_ids : [];
return [
  {
    json: {
      query: src.message,
      topK: 5,
      threshold: 0.3,
      includeDocumentId: src.document_id || '',
      // Фильтр по проекту: непустой набор → wf_rag ограничит выдачу этими документами.
      includeDocumentIds: includeIds.length ? includeIds : undefined,
    },
  },
];

// Готовим 1 input item для wf_rag_search из /rag/search-запроса.
const src = $('[ragSearch] Parse Request').first().json || {};
const includeIds = Array.isArray(src.document_ids) ? src.document_ids : [];
return [
  {
    json: {
      query: src.query,
      topK: 10,
      threshold: src.threshold || 0,
      excludeDocumentId: src.exclude_document_id || '',
      // Фильтр по проекту: непустой набор → wf_rag ограничит выдачу этими документами.
      includeDocumentIds: includeIds.length ? includeIds : undefined,
    },
  },
];
